// SymForce runner for the plane SLAM benchmark -- the generated-code path:
// the residuals are defined symbolically in ../symforce_gen.py,
// code-generated by SymForce into flattened C++ linearization functions
// (symforce_gen/*_factor.h), and executed by SymForce's own C++
// sym::Optimizer (LM). Templated over double/float.
//
// Poses are sym::Pose3 (quaternion + translation, SymForce's native
// decoupled retraction); a plane is a V3 (dy, dz, c) fixed tangent chart
// around its initial normal, the anchor rotation baked into each
// observation as a constant -- the same formulation as the factrs runner.
// The gauge is a strong prior on pose 0 (zero at the start point).
//
//   symforce_plane <scene.txt> <f64|f32> <solution_out>
//
// Probes + protocol line via ../../cpp/bench.h. SYMFORCE_LAMBDA0 overrides
// the initial damping (default 1e-10, a problem-appropriate
// near-Gauss-Newton value; SymForce ships 1.0).

#include "../../cpp/bench.h"

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include <Eigen/Dense>
#include <symforce/opt/factor.h>
#include <symforce/opt/key.h>
#include <symforce/opt/optimizer.h>

#include "symforce_gen/obs_factor.h"
#include "symforce_gen/odo_factor.h"
#include "symforce_gen/prior_factor.h"

struct Scene {
    std::vector<Eigen::Vector3d> t;
    std::vector<Eigen::Quaterniond> q;
    std::vector<Eigen::Matrix3d> anchor;    // per plane: initial normal's frame
    std::vector<double> pc;                 // per plane: c / |n| at init
    struct O { int i, j; Eigen::Vector3d tm; Eigen::Matrix3d rm_t; double wt, wr; };
    struct B { int p, l; Eigen::Vector3d nm; double cm, waz, wel, wd; };
    std::vector<O> odos;
    std::vector<B> obss;
};

// Rotation taking (1,0,0) to the (normalized) direction -- the chart
// anchor, matching the factrs runner's quaternd::from_two_vectors frame.
static Eigen::Matrix3d anchor_of(const Eigen::Vector3d& dir) {
    Eigen::Quaterniond q = Eigen::Quaterniond::FromTwoVectors(
        Eigen::Vector3d(1, 0, 0), dir.normalized());
    return q.toRotationMatrix();
}

static Scene load(const char* path) {
    Scene s;
    std::ifstream in(path);
    if (!in) { fprintf(stderr, "cannot read %s\n", path); exit(1); }
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ss(line);
        std::string tag; ss >> tag;
        if (tag == "pose") {
            double x, y, z, qw, qx, qy, qz;
            ss >> x >> y >> z >> qw >> qx >> qy >> qz;
            s.t.emplace_back(x, y, z);
            s.q.push_back(Eigen::Quaterniond(qw, qx, qy, qz).normalized());
        } else if (tag == "plane") {
            double nx, ny, nz, c;
            ss >> nx >> ny >> nz >> c;
            Eigen::Vector3d n(nx, ny, nz);
            s.anchor.push_back(anchor_of(n));
            s.pc.push_back(c / n.norm());
        } else if (tag == "odom") {
            Scene::O o; double x, y, z, qw, qx, qy, qz, it_, ir;
            ss >> o.i >> o.j >> x >> y >> z >> qw >> qx >> qy >> qz;
            ss >> it_ >> it_ >> it_ >> ir >> ir >> ir;
            o.tm = Eigen::Vector3d(x, y, z);
            o.rm_t = Eigen::Quaterniond(qw, qx, qy, qz).toRotationMatrix().transpose();
            o.wt = sqrt(it_); o.wr = sqrt(ir);
            s.odos.push_back(o);
        } else if (tag == "obs") {
            Scene::B b; double nx, ny, nz, c, ia, ie, id;
            ss >> b.p >> b.l >> nx >> ny >> nz >> c >> ia >> ie >> id;
            Eigen::Vector3d n(nx, ny, nz);
            b.nm = n.normalized();
            b.cm = c / n.norm();
            b.waz = sqrt(ia); b.wel = sqrt(ie); b.wd = sqrt(id);
            s.obss.push_back(b);
        }
    }
    return s;
}

static const double PRIOR_W = 1e6;

template <typename Scalar>
static sym::Pose3<Scalar> make_pose(const Eigen::Vector3d& t, const Eigen::Quaterniond& q) {
    return sym::Pose3<Scalar>(sym::Rot3<Scalar>(q.template cast<Scalar>()),
                              t.template cast<Scalar>());
}

// Canonical cost of the initial estimate, evaluated by the GENERATED
// residual functions in double -- the harness cross-checks this against
// the reference cost function. The gauge prior is zero at the start point.
static double initial_cost(const Scene& s) {
    double cost = 0.0;
    Eigen::Matrix<double, 6, 1> r6;
    Eigen::Matrix<double, 3, 1> r3;
    for (const auto& o : s.odos) {
        sym::OdoFactor<double>(make_pose<double>(s.t[o.i], s.q[o.i]),
                               make_pose<double>(s.t[o.j], s.q[o.j]),
                               o.tm, o.rm_t, o.wt, o.wr, &r6);
        cost += r6.squaredNorm();
    }
    for (const auto& b : s.obss) {
        sym::ObsFactor<double>(make_pose<double>(s.t[b.p], s.q[b.p]),
                               Eigen::Vector3d(0, 0, s.pc[b.l]),
                               s.anchor[b.l], b.nm, b.cm, b.waz, b.wel, b.wd, &r3);
        cost += r3.squaredNorm();
    }
    sym::PriorFactor<double>(make_pose<double>(s.t[0], s.q[0]),
                             make_pose<double>(s.t[0], s.q[0]), PRIOR_W, &r6);
    cost += r6.squaredNorm();
    return cost;
}

template <typename Scalar>
static bench::Result solve(const Scene& s, int max_iters,
                           std::vector<double>* pose_out,
                           std::vector<double>* plane_out) {
    const int n = (int)s.t.size(), m = (int)s.anchor.size();
    sym::Values<Scalar> v;
    for (int i = 0; i < n; i++) v.Set(sym::Key('P', i), make_pose<Scalar>(s.t[i], s.q[i]));
    for (int j = 0; j < m; j++)
        v.Set(sym::Key('L', j), Eigen::Matrix<Scalar, 3, 1>(0, 0, Scalar(s.pc[j])));
    for (int k = 0; k < (int)s.odos.size(); k++) {
        const auto& o = s.odos[k];
        v.Set(sym::Key('a', k), o.tm.template cast<Scalar>().eval());
        v.Set(sym::Key('b', k), o.rm_t.template cast<Scalar>().eval());
        v.Set(sym::Key('c', k), Scalar(o.wt));
        v.Set(sym::Key('d', k), Scalar(o.wr));
    }
    for (int k = 0; k < (int)s.obss.size(); k++) {
        const auto& b = s.obss[k];
        v.Set(sym::Key('e', k), s.anchor[b.l].template cast<Scalar>().eval());
        v.Set(sym::Key('f', k), b.nm.template cast<Scalar>().eval());
        v.Set(sym::Key('g', k), Scalar(b.cm));
        v.Set(sym::Key('h', k), Scalar(b.waz));
        v.Set(sym::Key('i', k), Scalar(b.wel));
        v.Set(sym::Key('j', k), Scalar(b.wd));
    }
    v.Set(sym::Key('q'), make_pose<Scalar>(s.t[0], s.q[0]));
    v.Set(sym::Key('w'), Scalar(PRIOR_W));

    std::vector<sym::Factor<Scalar>> factors;
    factors.reserve(s.odos.size() + s.obss.size() + 1);
    for (int k = 0; k < (int)s.odos.size(); k++) {
        const auto& o = s.odos[k];
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::OdoFactor<Scalar>,
            {sym::Key('P', o.i), sym::Key('P', o.j), sym::Key('a', k), sym::Key('b', k),
             sym::Key('c', k), sym::Key('d', k)},
            {sym::Key('P', o.i), sym::Key('P', o.j)}));
    }
    for (int k = 0; k < (int)s.obss.size(); k++) {
        const auto& b = s.obss[k];
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::ObsFactor<Scalar>,
            {sym::Key('P', b.p), sym::Key('L', b.l), sym::Key('e', k), sym::Key('f', k),
             sym::Key('g', k), sym::Key('h', k), sym::Key('i', k), sym::Key('j', k)},
            {sym::Key('P', b.p), sym::Key('L', b.l)}));
    }
    factors.push_back(sym::Factor<Scalar>::Hessian(
        sym::PriorFactor<Scalar>,
        {sym::Key('P', 0), sym::Key('q'), sym::Key('w')},
        {sym::Key('P', 0)}));

    auto params = sym::DefaultOptimizerParams();
    params.iterations = max_iters;
    // Shared termination class, per precision: f32 epsilon is 1.2e-7, so a
    // relative test at the double-precision class measures rounding noise
    // and costs rejected steps (30 attempts for 6 accepted, against 8 for
    // 5 here).
    params.early_exit_min_reduction = std::is_same<Scalar, double>::value ? 1e-7 : 1e-5;
    if (const char* t = getenv(std::is_same<Scalar, double>::value ? "PLANE_TOL" : "PLANE_TOL_F32"))
        params.early_exit_min_reduction = atof(t);
    // Problem-appropriate initial damping. SymForce ships 1.0;
    // near-Gauss-Newton values spend damping retries on the long loops,
    // where this accepts every step (7 of 7 at 900 poses against 18
    // attempts at 1e-10). Nothing below 300 poses moves.
    params.initial_lambda = 3e-3;
    if (const char* l = getenv("SYMFORCE_LAMBDA0")) params.initial_lambda = atof(l);

    sym::Optimizer<Scalar> optimizer(params, std::move(factors));
    auto t0 = std::chrono::steady_clock::now();
    auto stats = optimizer.Optimize(v);
    double ms = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - t0).count();

    int accepted = 0;
    for (const auto& it : stats.iterations) if (it.update_accepted) accepted++;
    if (pose_out) {
        pose_out->clear();
        for (int i = 0; i < n; i++) {
            auto p = v.template At<sym::Pose3<Scalar>>(sym::Key('P', i));
            auto qd = p.Rotation().Data();  // x, y, z, w
            auto td = p.Position();
            double vals[7] = {double(td[0]), double(td[1]), double(td[2]),
                              double(qd[3]), double(qd[0]), double(qd[1]), double(qd[2])};
            pose_out->insert(pose_out->end(), vals, vals + 7);
        }
        plane_out->clear();
        for (int j = 0; j < m; j++) {
            auto x = v.template At<Eigen::Matrix<Scalar, 3, 1>>(sym::Key('L', j));
            double dy = double(x[0]), dz = double(x[1]), c = double(x[2]);
            double s2 = 1.0 + (dy * dy + dz * dz) / 4.0;
            Eigen::Vector3d local(1.0 - (dy * dy + dz * dz) / (2.0 * s2), dz / s2, -dy / s2);
            Eigen::Vector3d nw = s.anchor[j] * local;
            double vals[4] = {nw.x(), nw.y(), nw.z(), c};
            plane_out->insert(plane_out->end(), vals, vals + 4);
        }
    }
    // SymForce records the initial error state as an entry with iteration =
    // -1, before any step is taken; discount it so accepted and attempts
    // mean the same here as in every other runner.
    return bench::Result{ms, accepted, std::max(0, (int)stats.iterations.size() - 1)};
}

template <typename Scalar>
static void run(const Scene& s, const char* solution_out) {
    std::vector<double> poses, planes;
    bench::report(
        [&](int n) { return solve<Scalar>(s, n, nullptr, nullptr); },
        [&]() {
            bench::Result r = solve<Scalar>(s, bench::full_iters(200), &poses, &planes);
            // The cross-check the harness asserts: SymForce's own generated
            // residuals, in double, must value the initial estimate at the
            // reference cost.
            r.initial_cost = initial_cost(s);
            return r;
        });

    std::ofstream out(solution_out);
    out.precision(17);
    for (size_t i = 0; i + 6 < poses.size(); i += 7)
        out << poses[i] << " " << poses[i + 1] << " " << poses[i + 2] << " "
            << poses[i + 3] << " " << poses[i + 4] << " " << poses[i + 5] << " "
            << poses[i + 6] << "\n";
    for (size_t j = 0; j + 3 < planes.size(); j += 4)
        out << planes[j] << " " << planes[j + 1] << " " << planes[j + 2] << " "
            << planes[j + 3] << "\n";
}

int main(int argc, char** argv) {
    // Silence SymForce's atexit profiling table (it would interleave with
    // the JSON protocol line on stdout).
    setenv("SYMFORCE_TIC_TOC_QUIET", "1", 0);
    if (argc < 4) { fprintf(stderr, "usage: %s <scene.txt> <f64|f32> <solution_out>\n", argv[0]); return 1; }
    Scene s = load(argv[1]);
    if (std::string(argv[2]) == "f32") run<float>(s, argv[3]);
    else run<double>(s, argv[3]);
    return 0;
}
